std::complex<double> FPFPsc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };

  double s123 = t(j1,j2,j3);
  double s234 = t(j2,j3,j4);
  double s23 = s(j2,j3);
  double s56 = s(j5,j6);

  // @coverage-probe
  std::complex<double> FPFPsc_value =
      za(j3,j4)*std::pow(za(j5,j2),2)*std::pow(zb(j2,j4),2)
      /(za(j1,j2)*za(j5,j6)*za(j2,j4))
      *Ls1(-s23,-s234,-s(j3,j4),-s234)
      /std::pow(s234,2)

    - za(j1,j3)*za(j3,j4)*std::pow(za(j5,j1),2)
      /(za(j1,j2)*za(j2,j3)*za(j5,j6)*std::pow(za(j4,j1),3))
      *Lsm1_2me(s123,s234,s23,s56)

    + FPFPsc1(j1,j2,j3,j4,j5,j6,za,zb)*lnrat(-s234,-s56)
    + FPFPsc2(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s123,-s23)/s23
    + FPFPsc3(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s23)/s23
    + FPFPsc4(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s123,-s56)/s56
    + FPFPsc5(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s123,-s56)/s56
    + FPFPsc6(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s56)/s56
    + FPFPsc7(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s56)/s56
    + FPFPsc8(j1,j2,j3,j4,j5,j6,za,zb)*L1(-s23,-s234)/std::pow(s234,2)
    + FPFPsc9(j1,j2,j3,j4,j5,j6,za,zb)*L1(-s(j3,j4),-s234)/std::pow(s234,2)
    + FPFPsc10(j1,j2,j3,j4,j5,j6,za,zb)*L1(-s123,-s56)/std::pow(s56,2)
    + FPFPsc11(j1,j2,j3,j4,j5,j6,za,zb)*L1(-s234,-s56)/std::pow(s56,2)

    + 0.5*zb(j2,j4)*zab2(j1,j2,j4,j6)*zab2(j3,j2,j4,j6)
      /(za(j1,j2)*za(j4,j1)*zb(j5,j6)*t(j1,j2,j4)*s234)

    + 0.5*za(j2,j4)*std::pow(zb(j2,j4),2)*za(j5,j1)*za(j5,j3)
      /(za(j1,j2)*za(j4,j1)*za(j5,j6)*t(j1,j2,j4)*s234)

    + 0.5*za(j1,j3)*std::pow(za(j3,j5),2)
      /(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*za(j5,j6));

  return FPFPsc_value;
}

namespace {
  std::complex<double> FPFPsc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -0.5*za(j1,j3)*std::pow(za(j5,j3),2)
        /(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*za(j5,j6));
  }

  std::complex<double> FPFPsc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -za(j1,j3)*std::pow(za(j5,j1),2)*zb(j1,j2)
        /(za(j1,j2)*za(j5,j6)*std::pow(za(j4,j1),2));
  }

  std::complex<double> FPFPsc3(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return za(j3,j4)*std::pow(za(j5,j1),2)*zb(j2,j4)
        /(za(j1,j2)*za(j5,j6)*std::pow(za(j4,j1),2));
  }

  std::complex<double> FPFPsc4(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
    };

    return -za(j1,j3)*za(j5,j1)*za(j5,j4)*zab2(j3,j1,j2,j4)
        /(za(j1,j2)*za(j2,j3)*za(j5,j6)*std::pow(za(j4,j1),2));
  }

  std::complex<double> FPFPsc5(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return za(j1,j3)*zb(j6,j4)*za(j5,j3)/(za(j1,j2)*za(j2,j3)*za(j4,j1));
  }

  std::complex<double> FPFPsc6(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
    };

    return za(j1,j3)*std::pow(za(j5,j1),2)*zab2(j3,j2,j4,j1)
        /(za(j1,j2)*za(j2,j3)*za(j5,j6)*std::pow(za(j4,j1),2));
  }

  std::complex<double> FPFPsc7(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -std::pow(za(j1,j3),2)*za(j5,j3)*zb(j6,j1)
        /(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1));
  }

  std::complex<double> FPFPsc8(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -0.5*za(j2,j3)*std::pow(za(j5,j4),2)*std::pow(zb(j4,j2),2)
        /(za(j1,j4)*za(j5,j6)*za(j2,j4));
  }

  std::complex<double> FPFPsc9(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -0.5*std::pow(za(j5,j2),2)*std::pow(zb(j2,j4),2)*za(j4,j3)
        /(za(j1,j2)*za(j5,j6)*za(j2,j4));
  }

  std::complex<double> FPFPsc10(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -za(j1,j3)*za(j3,j4)*za(j5,j6)*std::pow(zb(j6,j4),2)
        /(za(j1,j2)*za(j2,j3)*za(j4,j1));
  }

  std::complex<double> FPFPsc11(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    return -0.5*std::pow(za(j1,j3),3)*za(j5,j6)*std::pow(zb(j6,j1),2)
        /(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1));
  }
}

